contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount, address logAddr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (0)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        // Before initialization SetLogFile succeeds
        bool revertedBefore;
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;
        // deposit to make the contract usable
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;
        uint balAfterDeposit = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethAfterDeposit = address(c).balance;
        // initialize
        c.Initialized(); if (__ESBMC_reverted()) return;
        // after initialization SetLogFile reverts
        bool revertedAfter;
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedAfter = true; } else { revertedAfter = false; }
        // deposits still work after initialization
        c.Deposit{value: 0}(); if (__ESBMC_reverted()) return;
        assert(revertedAfter && c.balances(address(this)) >= balAfterDeposit && address(c).balance >= ethAfterDeposit);
    }
    receive() external payable {}
}

